INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S4-Q19$batch08$, 156, 4, 19, $batch08$Sufficient Assumption$batch08$, $batch08$I promised Bernie that I would answer his question. He asked me whether his project had been approved. I misunderstood and thought he had asked whether I had approved it. I said, truthfully, “I would approve it if I could, but I don’t have the authority to do so—that is up to Dorothy, and she hasn’t yet made a decision.” Thus, I fulfilled my promise to Bernie.$batch08$, $batch08$Which one of the following, if assumed, enables the conclusion above to be properly drawn?$batch08$, $batch08$A$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$All there is to answering a question is giving the questioner the information requested.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$No person can be held accountable for another person’s decisions.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$The person responsible for a decision is the one who should explain the decision.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$One need not fulfill a promise in order to do the best that could be done to fulfill it.$batch08$, $batch08$Opposite$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$Making a promise always obliges a person to keep it.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Conclusion$batch08$, $batch08$I fulfilled my promise to answer Bernie's question.$batch08$), (1, $batch08$Evidence$batch08$, $batch08$Bernie asked whether his project was approved. I misunderstood and said I'd approve it if I could, but Dorothy decides and hasn't decided yet.$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$The speaker answered the wrong question, but still told Bernie what he wanted to know: no decision has been made. The conclusion only follows if answering a question is just a matter of giving the information asked for, whatever you thought the question was.$batch08$), (3, $batch08$Goal$batch08$, $batch08$Answering a question = giving the requested information.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$If answering is just giving the requested information, then telling Bernie that Dorothy hasn't decided answers him. The promise is kept.$batch08$), ($batch08$B$batch08$, $batch08$Accountability for Dorothy's decision has nothing to do with whether Bernie got an answer.$batch08$), ($batch08$C$batch08$, $batch08$Who should explain a decision doesn't tell us whether this answer counts.$batch08$), ($batch08$D$batch08$, $batch08$This is about falling short of a promise. The conclusion says the promise was fulfilled.$batch08$), ($batch08$E$batch08$, $batch08$That promises should be kept doesn't show this one was.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S4-Q19$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
